import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits around.

    x must be in 0..255 and k in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_examples() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b00000001, 7) == 0b10000000
    assert rotl8(0b11110000, 4) == 0b00001111
    assert rotl8(0b10110010, 3) == 0b10010101


def test_rotl8_zero_shift_is_identity() -> None:
    for x in range(256):
        assert rotl8(x, 0) == x


def test_rotl8_fixed_points() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_single_bit_wraps() -> None:
    for k in range(8):
        assert rotl8(0x80, k) == (0x80 << k) % 255 or k == 0
    assert rotl8(0x80, 1) == 0x01
    assert rotl8(0x80, 7) == 0x40


@pytest.mark.parametrize("k", range(8))
def test_rotl8_matches_string_reference(k: int) -> None:
    for x in range(256):
        bits = format(x, "08b")
        expected = int(bits[k:] + bits[:k], 2)
        assert rotl8(x, k) == expected


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
